class _Cursor:
    def __init__(self, answers: dict[str, list[tuple]]) -> None: self._answers = answers; self._rows: list[tuple] = []
    def execute(self, sql: str) -> None: self._rows = self._answers[sql.strip()]
    def fetchall(self) -> list[tuple]: return self._rows
    def __enter__(self): return self
    def __exit__(self, *_: object) -> None: return None
class _Connection:
    def __init__(self, answers: dict[str, list[tuple]]) -> None: self._answers = answers
    def cursor(self) -> _Cursor: return _Cursor(self._answers)
    def __enter__(self): return self
    def __exit__(self, *_: object) -> None: return None
def _db(violations: list[tuple], population: int, signals: list[tuple] | None = None): answers = {"V": violations, "P": [(population,)], "S": signals or []}; return lambda _url: _Connection(answers)
def _run(violations, population, exemptions=None, *, invariant=ONE, signals=None, **kwargs): return check( "postgresql://unused", today=TODAY, exemptions=exemptions or {}, invariants=(invariant,), connect=_db(violations, population, signals), **kwargs, )
