SEEDED_CUTOFF = date(2026, 3, 31); REVENUE_UNIVERSE = "universe:topt-us-2026-03-31"
def _months_before(day: date, months: int) -> date: year, month_index = divmod(day.year * 12 + day.month - 1 - months, 12); return date(year, month_index + 1, min(day.day, calendar.monthrange(year, month_index + 1)[1]))
def test_a_head_whose_revenue_periods_are_recent_passes( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: issuers = [ _issuer("current", "cur0", revenue_period_end=date(2025, 12, 31)), _issuer("lagging", "lag0", revenue_period_end=date(2024, 12, 31)), ]; _seed_head(conn, REVENUE_UNIVERSE, issuers); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 0, output; assert f"ok       {REVENUE_INVARIANT}: 2 row(s) examined" in output
def test_a_revenue_period_from_2018_fails_and_names_the_issuer( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: issuers = [ _issuer("current", "cur0", revenue_period_end=date(2025, 12, 31)), _issuer("xel", "xel0", revenue_period_end=date(2018, 12, 31)), ]; run_id = _seed_head(conn, REVENUE_UNIVERSE, issuers); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 1, output; assert f"{REVENUE_INVARIANT}: 1 violation(s)" in output; assert f"Offending rows: {REVENUE_UNIVERSE} {run_id} issuer:xel 2018-12-31 2026-03-31" in output
def test_the_limit_is_the_maximum_input_age_days_of_the_live_definition( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: assert _module._MAX_INPUT_AGE_DAYS == 455; limit = SEEDED_CUTOFF - timedelta(days=_module._MAX_INPUT_AGE_DAYS); assert limit == date(2024, 12, 31); _seed_head(conn, REVENUE_UNIVERSE, [_issuer("edge", "edge0", revenue_period_end=limit)]); assert _parity_verdict(conn, capsys, REVENUE_INVARIANT)[0] == 0; conn.rollback(); _seed_head(conn, REVENUE_UNIVERSE, [_issuer("late", "late0", revenue_period_end=limit - timedelta(days=1))]); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 1, output; assert f"issuer:late {limit - timedelta(days=1)} 2026-03-31" in output
def test_an_unavailable_result_with_a_named_reason_may_carry_an_old_period( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: issuers = [ _issuer("current", "cur0", revenue_period_end=date(2025, 12, 31)), _issuer("refused", "ref0", available=False, reasons=("stale_input",), revenue_period_end=date(2018, 12, 31)), ]; _seed_head(conn, REVENUE_UNIVERSE, issuers); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 0, output; assert f"ok       {REVENUE_INVARIANT}: 1 row(s) examined" in output
def test_a_head_that_states_no_revenue_period_fails_by_name( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: run_id = _seed_head(conn, REVENUE_UNIVERSE, [_issuer("undated", "und0")]); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 1, output; assert f"{REVENUE_INVARIANT}: 1 violation(s)" in output; assert f"Offending rows: {REVENUE_UNIVERSE} {run_id} no-result-states-a-revenue-period - -" in output
def test_a_head_with_dated_results_cannot_hide_a_head_with_none( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: _seed_head(conn, REVENUE_UNIVERSE, [_issuer("dated", "dat0", revenue_period_end=date(2025, 12, 31))]); undated_run = _seed_head(conn, "universe:canary-us-2026-06-30", [_issuer("undated", "und0")]); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 1, output; assert f"{REVENUE_INVARIANT}: 1 violation(s)" in output; assert f"universe:canary-us-2026-06-30 {undated_run} no-result-states-a-revenue-period - -" in output
def test_a_head_with_some_dated_and_some_undated_results_is_not_judged_on_the_undated_rows( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: _seed_head( conn, REVENUE_UNIVERSE, [_issuer("dated", "dat0", revenue_period_end=date(2025, 12, 31)), _issuer("undated", "und0")], ); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 0, output; assert f"ok       {REVENUE_INVARIANT}: 1 row(s) examined" in output
def test_a_head_whose_results_are_all_unavailable_is_not_judged_by_this_invariant( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: _seed_head(conn, REVENUE_UNIVERSE, [_issuer("dated", "dat0", revenue_period_end=date(2025, 12, 31))]); _seed_head( conn, "universe:canary-us-2026-06-30", [_issuer("refused", "ref0", available=False, reasons=("stale_input",))], ); code, output = _parity_verdict(conn, capsys, REVENUE_INVARIANT); assert code == 0, output; assert f"ok       {REVENUE_INVARIANT}: 1 row(s) examined" in output
def test_the_expected_inputs_follow_the_class_of_the_issuer() -> None:
    pairs = set(_module.EXPECTED_INPUTS); leaves = {"stockholders_equity", "preferred_stock_value", "goodwill", "intangible_assets_net_excluding_goodwill"}
    for leaf in leaves: assert (leaf, "financial") in pairs; assert (leaf, "non_financial") not in pairs and (leaf, "insurance") not in pairs
    assert ("total_assets", "financial") not in pairs; assert ("total_assets", "non_financial") in pairs and ("total_assets", "insurance") in pairs; assert ("net_income", "financial") in pairs and ("net_income", "non_financial") in pairs, "PEG reads every class"
DISPLAY_NAME_INVARIANT = "governed-entities-resolve-display-name"
def test_governed_entities_resolve_display_name_passes_with_real_names_and_fails_on_null_or_ticker( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None:
    issuers = [ _issuer("jpm", "jpm0", revenue_period_end=date(2025, 12, 31)), _issuer("lly", "lly0", revenue_period_end=date(2025, 12, 31)), ]; run_id = _seed_head(conn, REVENUE_UNIVERSE, issuers); code, output = _parity_verdict(conn, capsys, DISPLAY_NAME_INVARIANT); assert code == 1, output; assert f"{DISPLAY_NAME_INVARIANT}: 2 violation(s)" in output
    for issuer_id, name in [("issuer:jpm", "JPMorgan Chase & Co."), ("issuer:lly", "Eli Lilly and Company")]: conn.execute( "insert into staging.kg_entities (id, entity_type, display_name) values (%s, 'company', %s)", (issuer_id, name), )
    code_ok, output_ok = _parity_verdict(conn, capsys, DISPLAY_NAME_INVARIANT); assert code_ok == 0, output_ok; assert f"ok       {DISPLAY_NAME_INVARIANT}: 2 row(s) examined" in output_ok; assert run_id is not None
ENTITY_IDENTITY_UNIQUE_INVARIANT = "entity-identity-unique-per-entity"; FUND_WEIGHTS_INVARIANT = "fund-virtual-company-weights-conserved"
def test_entity_identity_unique_and_fund_weights_conserved_structure_and_behavior() -> None: (unique_inv,) = [inv for inv in _module.INVARIANTS if inv.id == ENTITY_IDENTITY_UNIQUE_INVARIANT]; assert "from mart.entity_identity" in unique_inv.violations; assert "group by entity_id" in unique_inv.violations; assert "having count(*) > 1" in unique_inv.violations; assert "select count(*) from mart.entity_identity" in unique_inv.population; unique_answers = { unique_inv.violations.strip(): [], unique_inv.population.strip(): [(338,)], }; assert ( check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(unique_inv,), connect=lambda _url: _Connection(unique_answers), ) == 0 ); unique_answers[unique_inv.violations.strip()] = [("00000000-0000-0000-0000-000000001641", "2")]; assert ( check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(unique_inv,), connect=lambda _url: _Connection(unique_answers), ) == 1 ); (weights_inv,) = [inv for inv in _module.INVARIANTS if inv.id == FUND_WEIGHTS_INVARIANT]; assert "from mart.fund_virtual_company" in weights_inv.violations; assert "total_weight_pct > 105" in weights_inv.violations; assert "resolved_weight_pct > total_weight_pct" in weights_inv.violations; assert "valued_weight_pct > resolved_weight_pct" in weights_inv.violations; assert "select count(*) from mart.fund_virtual_company" in weights_inv.population; weights_answers = { weights_inv.violations.strip(): [], weights_inv.population.strip(): [(4,)], }; assert ( check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(weights_inv,), connect=lambda _url: _Connection(weights_answers), ) == 0 ); weights_answers[weights_inv.violations.strip()] = [ ("capture-run:1641", "etf:series:QQQ", "198.2", "198.2", "190.0") ]; assert ( check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(weights_inv,), connect=lambda _url: _Connection(weights_answers), ) == 1 )
def test_entity_identity_unique_per_entity_passes_with_dual_kg_rows_and_fails_on_duplicate( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None:
    entity_uuid = _mint_listing(conn, "listing:xnas:goog")
    for kg_id, name in ((entity_uuid, "Alphabet UUID"), ("listing:xnas:goog", "Alphabet Legacy")): conn.execute( "insert into staging.kg_entities (id, entity_type, display_name) values (%s, 'company', %s)", (kg_id, name), )
    code, output = _parity_verdict(conn, capsys, ENTITY_IDENTITY_UNIQUE_INVARIANT); assert code == 0, output; assert f"ok       {ENTITY_IDENTITY_UNIQUE_INVARIANT}: 1 row(s) examined" in output; (invariant,) = [inv for inv in _module.INVARIANTS if inv.id == ENTITY_IDENTITY_UNIQUE_INVARIANT]; answers = { invariant.violations.strip(): [(entity_uuid, "2")], invariant.population.strip(): [(2,)], }; failing = check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(invariant,), connect=lambda _url: _Connection(answers), ); assert failing == 1
def test_fund_virtual_company_weights_conserved_passes_valid_row_and_fails_on_fanout( conn: psycopg.Connection, capsys: pytest.CaptureFixture[str] ) -> None: conn.execute( "\n        insert into mart.fund_virtual_company (\n            run_id, fund_id, report_period, transaction_time, cutoff,\n            definition_version, definition_sha256, weighted_valuation_gap, valuation_basis,\n            total_weight_pct, resolved_weight_pct, valued_weight_pct, lines, valued_lines, confidence,\n            availability_status, source_evidence_status, factor_validation_status\n        ) values (\n            'capture-run:1641', 'etf:series:QQQ', '2026-06-30', '2026-06-30T00:00:00Z',\n            '2026-06-30T00:00:00Z', 'v0', repeat('a', 64), 0.12, 'price_to_gross_profit',\n            99.8, 98.5, 95.0, 100, 95, 0.90,\n            'available', 'verified', 'accepted'\n        )\n        " ); code, output = _parity_verdict(conn, capsys, FUND_WEIGHTS_INVARIANT); assert code == 0, output; assert f"ok       {FUND_WEIGHTS_INVARIANT}: 1 row(s) examined" in output; (invariant,) = [inv for inv in _module.INVARIANTS if inv.id == FUND_WEIGHTS_INVARIANT]; answers = { invariant.violations.strip(): [("capture-run:1641", "etf:series:QQQ", "198.2", "198.2", "190.0")], invariant.population.strip(): [(1,)], }; failing = check( "postgresql://unused", today=TODAY, exemptions={}, invariants=(invariant,), connect=lambda _url: _Connection(answers), ); assert failing == 1
